select case when a.status in ('CLOSED', 'OPEN') then 'core' else 'other' end as status_group, a.account_type, round((100 * sum(case when t.merchant = 'Lazada' then 1 else 0 end)) / count(*), 1) as pct_lazada, avg(t.amount) as avg_amount from transactions t inner join accounts a on t.account_id = a.id where a.status = 'OPEN' group by case when a.status in ('CLOSED', 'OPEN') then 'core' else 'other' end, a.account_type order by avg_amount desc
